"use client";

import { useState } from "react";
import Image from "next/image";
import type { Product, ProductStatus, ProductSize } from "@atelier/shared";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ProductAddDialog } from "./ProductAddDialog";
import { Search, Eye } from "lucide-react";
import { useUpdateProductStatus } from "../useProducts";
import { useProductSelection } from "@/contexts/ProductSelectionContext";
import { Button } from "@/components/ui/button";

interface ProductsTableProps {
  products: Product[];
  onProductSelect: (product: Product, size: ProductSize) => void;
  selectedProductId?: string;
  selectedSize?: ProductSize;
}

const statusLabels: Record<ProductStatus, string> = {
  pending: "未発注",
  in_production: "制作中",
  review: "レビュー待ち",
  revision: "修正中",
  ready: "公開可",
  published: "公開中",
};

export function ProductsTable({
  products,
  onProductSelect,
  selectedProductId,
  selectedSize,
}: ProductsTableProps) {
  const updateProductStatus = useUpdateProductStatus();
  const { togglePreview } = useProductSelection();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedStatus, setSelectedStatus] = useState<string>("all");
  const [selectedRowIds, setSelectedRowIds] = useState<Set<string>>(new Set());

  const statuses: ProductStatus[] = [
    "pending",
    "in_production",
    "review",
    "revision",
    "ready",
    "published",
  ];

  const filteredProducts = products.filter((product) => {
    const matchesSearch =
      searchQuery === "" ||
      product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      product.brand?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      product.sku?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus =
      selectedStatus === "all" || product.status === selectedStatus;
    return matchesSearch && matchesStatus;
  });

  const toggleRowSelection = (productId: string) => {
    const newSelection = new Set(selectedRowIds);
    if (newSelection.has(productId)) {
      newSelection.delete(productId);
    } else {
      newSelection.add(productId);
    }
    setSelectedRowIds(newSelection);
  };

  const handleProductClick = (product: Product) => {
    // デフォルトでMサイズを選択
    onProductSelect(product, "M");
    // プレビューを開く
    togglePreview();
  };

  return (
    <div className="flex flex-col space-y-4">
      {/* Header with search, filter, and add button */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 flex-col gap-4 sm:flex-row">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
            <Input
              placeholder="商品を検索"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
          </div>
          <Select value={selectedStatus} onValueChange={setSelectedStatus}>
            <SelectTrigger className="w-full sm:w-[180px]">
              <SelectValue placeholder="ステータス" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">すべて</SelectItem>
              {statuses.map((status) => (
                <SelectItem key={status} value={status}>
                  {statusLabels[status]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <ProductAddDialog />
      </div>

      {/* Table */}
      <div className="rounded-md border overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow className="bg-gray-100">
              <TableHead className="w-12 sticky left-0 bg-gray-100 z-10">
                <Checkbox
                  checked={
                    filteredProducts.length > 0 &&
                    selectedRowIds.size === filteredProducts.length
                  }
                  onCheckedChange={(checked) => {
                    if (checked) {
                      setSelectedRowIds(
                        new Set(filteredProducts.map((p) => p.id))
                      );
                    } else {
                      setSelectedRowIds(new Set());
                    }
                  }}
                />
              </TableHead>
              <TableHead>画像</TableHead>
              <TableHead>商品名</TableHead>
              <TableHead>ブランド</TableHead>
              <TableHead>SKU</TableHead>
              <TableHead>ステータス</TableHead>
              <TableHead className="w-24">操作</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredProducts.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} className="text-center text-gray-500">
                  商品が見つかりませんでした
                </TableCell>
              </TableRow>
            ) : (
              filteredProducts.map((product) => (
                <TableRow
                  key={product.id}
                  className="hover:bg-gray-50"
                >
                  <TableCell
                    onClick={(e) => e.stopPropagation()}
                    className="sticky left-0 bg-white z-10"
                  >
                    <Checkbox
                      checked={selectedRowIds.has(product.id)}
                      onCheckedChange={() => toggleRowSelection(product.id)}
                    />
                  </TableCell>
                  <TableCell className="py-6">
                    {product.thumbnailUrl ? (
                      <div className="relative h-32 w-32 overflow-hidden rounded">
                        <Image
                          src={product.thumbnailUrl}
                          alt={product.name}
                          fill
                          className="object-contain"
                          sizes="128px"
                        />
                      </div>
                    ) : (
                      <div className="h-32 w-32 bg-gray-100 rounded flex items-center justify-center text-gray-400 text-xs">
                        画像なし
                      </div>
                    )}
                  </TableCell>
                  <TableCell className="font-medium py-6">{product.name}</TableCell>
                  <TableCell className="py-6">{product.brand || "-"}</TableCell>
                  <TableCell className="py-6">{product.sku || "-"}</TableCell>
                  <TableCell
                    className="py-6"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <Select
                      value={product.status}
                      onValueChange={(value: ProductStatus) => {
                        updateProductStatus.mutate({
                          id: product.id,
                          status: value,
                        });
                      }}
                    >
                      <SelectTrigger className="w-[140px]">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {statuses.map((status) => (
                          <SelectItem key={status} value={status}>
                            {statusLabels[status]}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </TableCell>
                  <TableCell
                    className="py-6"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        onProductSelect(product, "M");
                        togglePreview();
                      }}
                      className="gap-2"
                    >
                      <Eye className="h-4 w-4" />
                      プレビュー
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}
